package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.optim.univariate.GoalType;
import org.apache.commons.math3.optim.univariate.UnivariateRealOptimizer;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.apache.commons.math3.random.RandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_getFunctionValue_TriageGen3Test {

    @Mock
    private UnivariateRealOptimizer mockOptimizer;

    @Mock
    private RandomGenerator mockGenerator;

    @Mock
    private UnivariateRealFunction mockFunction;

    private MultiStartUnivariateRealOptimizer multiStartOptimizer;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // Constructor: MultiStartUnivariateRealOptimizer(UnivariateRealOptimizer optimizer, int starts, RandomGenerator generator)
        multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 10, mockGenerator);
    }

    @Test
    public void testGetFunctionValue_ReturnsExpectedValue() {
        // Arrange
        double expectedValue = 42.0;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The returned function value should match the value from the internal optimizer.", 
                     expectedValue, actualValue, 1e-15);
    }

    @Test
    public void testGetFunctionValue_WithNegativeValue() {
        // Arrange
        double expectedValue = -123.456;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The returned function value should handle negative numbers correctly.", 
                     expectedValue, actualValue, 1e-15);
    }

    @Test
    public void testGetFunctionValue_WithZero() {
        // Arrange
        double expectedValue = 0.0;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The returned function value should handle zero correctly.", 
                     expectedValue, actualValue, 1e-15);
    }

    @Test
    public void testGetFunctionValue_WithNaN() {
        // Arrange
        double expectedValue = Double.NaN;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The returned function value should handle NaN correctly.", 
                     expectedValue, actualValue, 0.0);
    }

    @Test
    public void testGetFunctionValue_WithInfinity() {
        // Arrange
        double expectedValue = Double.POSITIVE_INFINITY;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The returned function value should handle Infinity correctly.", 
                     expectedValue, actualValue, 0.0);
    }
}
